def summarize(rows):
    """Take a list of dicts with 'region' and 'revenue' keys and return
    a dict mapping region -> total revenue (float). Rows with a missing
    or unparseable revenue are ignored.
    """
    totals = {}
    for row in rows:
        revenue = row.get("revenue")
        if revenue is None:
            continue
        try:
            revenue = float(revenue)
        except (ValueError, TypeError):
            continue
        region = row.get("region")
        if region is None:
            continue
        totals[region] = totals.get(region, 0.0) + revenue
    return totals

