def test_basic():
    rows = [
        {"region": "NA", "revenue": 100},
        {"region": "EU", "revenue": 200},
        {"region": "NA", "revenue": 50},
    ]
    assert summarize(rows) == {"NA": 150.0, "EU": 200.0}


def test_numeric_strings():
    rows = [
        {"region": "NA", "revenue": "100"},
        {"region": "EU", "revenue": "200"},
    ]
    assert summarize(rows) == {"NA": 100.0, "EU": 200.0}


def test_missing_revenue():
    rows = [
        {"region": "NA", "revenue": None},
        {"region": "EU", "revenue": 200},
    ]
    assert summarize(rows) == {"EU": 200.0}


def test_unparseable_revenue():
    rows = [
        {"region": "NA", "revenue": "foo"},
        {"region": "EU", "revenue": 200},
    ]
    assert summarize(rows) == {"EU": 200.0}


def test_empty_list():
    assert summarize([]) == {}


def test_missing_region_ignored():
    rows = [
        {"revenue": 100},
        {"region": "EU", "revenue": 200},
    ]
    assert summarize(rows) == {"EU": 200.0}


def test_all_invalid():
    rows = [
        {"region": "NA", "revenue": None},
        {"region": "EU", "revenue": "bad"},
    ]
    assert summarize(rows) == {}

